package com.cookly.configuracion;
import com.cookly.seguridad.FiltroJwt; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import java.util.*;
@Configuration public class ConfiguracionSeguridad { @Bean PasswordEncoder codificador(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain cadena(HttpSecurity http,FiltroJwt filtro)throws Exception { return http.csrf(c->c.disable()).cors(c->c.configurationSource(cors())).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).headers(h->h.contentSecurityPolicy(c->c.policyDirectives("default-src 'self'"))).authorizeHttpRequests(a->a.requestMatchers("/api/v1/autenticacion/**","/api/v1/salud").permitAll().requestMatchers("/api/v1/administracion/**").hasRole("ADMINISTRADOR").requestMatchers("/api/v1/moderacion/**").hasAnyRole("MODERADOR","ADMINISTRADOR").anyRequest().authenticated()).addFilterBefore(filtro,UsernamePasswordAuthenticationFilter.class).build(); } @Bean CorsConfigurationSource cors(){ var c=new CorsConfiguration();c.setAllowedOriginPatterns(List.of("https://cookly.app","https://*.onrender.com","http://localhost:*","http://10.0.2.2:*"));c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));c.setAllowCredentials(false); var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;} }
